<?php require 'includes/functions.php'; if($_SERVER['REQUEST_METHOD']!=='POST') exit; $data=array_map('trim',$_POST); if(empty($data['nome'])||!filter_var($data['email']??'',FILTER_VALIDATE_EMAIL)||empty($data['assunto'])||empty($data['mensagem'])){http_response_code(422);exit('Dados inválidos.');} $s=db()->prepare('INSERT INTO contatos(nome,email,assunto,mensagem) VALUES(?,?,?,?)');$s->execute([$data['nome'],$data['email'],$data['assunto'],$data['mensagem']]); header('Location: index.php?contato=enviado#contato');
